#!/usr/bin/env python3
from pathlib import Path
import shutil, zipfile
import cairosvg
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Flowable, Image, HRFlowable
from reportlab.lib.units import mm

BASE = Path(__file__).resolve().parents[1]
SKILL = BASE / "skills" / "idjoy-seo"
PDF = SKILL / "resources" / "idjoy-seo-ai-search-checklist.pdf"
LOGO_SVG = SKILL / "assets" / "idjoy-logo.svg"
LOGO_PNG = SKILL / "assets" / "idjoy-logo.png"
